def get_installed_packages(self) -> List[Dict[str, any]]:
    """Get installed DNF packages with license information."""
    try:
        # Try dnf first, fall back to yum
        cmd = "dnf" if shutil.which("dnf") else "yum"
        result = subprocess.run(
            [cmd, "list", "installed"],
            capture_output=True,
            text=True,
            check=True
        )

        packages = []
        in_packages = False
        for line in result.stdout.strip().split('\n'):
            if "Installed Packages" in line:
                in_packages = True
                continue

            if in_packages and line.strip():
                parts = line.split()
                if len(parts) >= 2:
                    name = parts[0].split('.')[0]  # Remove architecture
                    package_info = {
                        "name": name,
                        "display_name": name,
                        "version": parts[1],
                        "manager": "dnf",
                        "licenses": self._get_dnf_license(name, cmd)
                    }
                    packages.append(package_info)
        return packages
    except (subprocess.CalledProcessError, FileNotFoundError):
