def _get_dnf_license(self, package_name: str, cmd: str) -> List[str]:
    """Get license information for a DNF/YUM package."""
    try:
        result = subprocess.run(
            [cmd, "info", package_name],
            capture_output=True,
            text=True,
            check=True
        )

        # Parse the output to find license information
        for line in result.stdout.split('\n'):
            if line.startswith('License'):
                # Extract license after the colon
                license_part = line.split(':', 1)[1].strip()
                if license_part:
                    # Split multiple licenses (often separated by 'and', 'or', ',')
                    licenses = re.split(r'\s+(?:and|or|,)\s+', license_part)
                    return [lic.strip() for lic in licenses if lic.strip()]

        return ["unknown"]

    except (subprocess.CalledProcessError, FileNotFoundError):
        return ["unknown"]
